public record CartItem(string Name, int Quantity, decimal UnitPrice);

public record Cart(string Customer, List<CartItem> Items);

public static class Solution
{
    public static decimal CartSubtotal(Cart cart)
    {
        return cart.Items.Sum(item => item.Quantity * item.UnitPrice);
    }

    public static decimal CartTotal(Cart cart, decimal discountPercent)
    {
        decimal subtotal = CartSubtotal(cart);
        return subtotal * (1 - discountPercent / 100);
    }

    public static Cart? FindCart(IEnumerable<Cart> carts, string customer)
    {
        return carts.FirstOrDefault(cart => cart.Customer.ToLower() == customer.ToLower());
    }
}

