public static class Solution
{
    public static int CountPrimes(int n)
    {
        if (n <= 1) return 0;
        bool[] isPrime = new bool[n + 1];
        for (int i = 2; i * i <= n; i++)
        {
            if (!isPrime[i])
            {
                for (int j = i * i; j <= n; j += i)
                {
                    isPrime[j] = true;
                }
            }
        }
        int count = 0;
        for (int i = 2; i <= n; i++)
        {
            if (!isPrime[i])
            {
                count++;
            }
        }
        return count;
    }
}

