public static class Solution
{
    public static List<int> UniqueInOrder(int[] numbers)
    {
        HashSet<int> seen = new HashSet<int>();
        List<int> result = new List<int>();

        foreach (int number in numbers)
        {
            if (!seen.Contains(number))
            {
                seen.Add(number);
                result.Add(number);
            }
        }

        return result;
    }
}

