public static class Solution
{
    public static Dictionary<string, List<int>> GroupByParity(int[] numbers)
    {
        var result = new Dictionary<string, List<int>>();

        foreach (var number in numbers)
        {
            if (number % 2 == 0)
            {
                if (!result.ContainsKey("even"))
                {
                    result["even"] = new List<int>();
                }
                result["even"].Add(number);
            }
            else
            {
                if (!result.ContainsKey("odd"))
                {
                    result["odd"] = new List<int>();
                }
                result["odd"].Add(number);
            }
        }

        return result;
    }
}

