public static class Solution
{
    public static int BinarySearch(int[] sorted, int target)
    {
        int left = 0;
        int right = sorted.Length - 1;

        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            if (sorted[mid] == target)
            {
                return mid;
            }
            else if (sorted[mid] < target)
            {
                left = mid + 1;
            }
            else
            {
                right = mid - 1;
            }
        }

        return -1;
    }
}

