public static class Solution
{
    public static Dictionary<string, string> ParseKeyValues(string s)
    {
        if (string.IsNullOrWhiteSpace(s))
        {
            return new Dictionary<string, string>();
        }

        var keyValuePairs = s.Split(';').Select(pair => pair.Trim()).ToDictionary(pair => pair.Split('=')[0], pair => pair.Split('=')[1]);

        foreach (var pair in keyValuePairs)
        {
            if (string.IsNullOrEmpty(pair.Key) || string.IsNullOrEmpty(pair.Value))
            {
                throw new FormatException("Key or value is empty.");
            }
        }

        var duplicateKeys = keyValuePairs.GroupBy(pair => pair.Key).Any(group => group.Count() > 1);
        if (duplicateKeys)
        {
            throw new FormatException("Duplicate key found.");
        }

        return keyValuePairs;
    }
}

