using System;
using System.Text.RegularExpressions;

public static class Solution
{
    public static Color? ParseHexColor(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return null;
        }

        text = text.Trim();

        if (!Regex.IsMatch(text, @"^#[0-9A-Fa-f]{6}$"))
        {
            return null;
        }

        var parts = text.Substring(1).ToCharArray();

        if (parts.Length != 3)
        {
            return null;
        }

        byte red = Convert.ToByte(parts[0], 16);
        byte green = Convert.ToByte(parts[1], 16);
        byte blue = Convert.ToByte(parts[2], 16);

        return new Color(red, green, blue);
    }
}

public sealed record Color(byte Red, byte Green, byte Blue);
